def missing(block, names):
    """Листы файла, которых нет в каталоге (catalog.missing): сборка их создала, а каталог их не знает."""
    from .catalog import missing as m_
    return m_(block, names)


def resolve(block, sheet):
    """Старое имя листа (из данных блока) → имя листа в файле отчёта."""
    return LINKS.get(block, {}).get(sheet, sheet)


def present(block, selected=None):
    """Вкладки выводимых листов файла блока в порядке каталога."""
    from .catalog import order, tab
    return [tab(block, n) for n in order(block)]
